// HA BRIDGE publisher for HeishaMoNR (v1.2.1) - separate tab, does not touch Ed's logic.
// Reads the flow's own settings objects (global, file storage) and publishes
// every value to MQTT, plus HA MQTT discovery configs once per key per restart.
// Output 1: MQTT messages. Output 2: dashboard status (values count + timestamps).
// Requires MQTT discovery enabled in HA (it is, if HeishaMon entities auto-appeared).

const STATE_BASE = 'heishamon/nr';      // state topics: heishamon/nr/<key>
const DISC_BASE  = 'homeassistant/sensor/heishamon_nr'; // discovery topics

// Objects the flow persists (name = MQTT/HA prefix)
const OBJECTS = {
    rtc:   'F_RTC',
    ss:    'F_SS',
    ccc:   'F_CCC',
    solar: 'F_SOLAR',
    cool:  'F_COOL',
    pump:  'F_ReducePumpSpeed',
    nr_room:    'NightReductionRoomSetpoint',
    nr_water:   'NightReductionWaterTemp',
    sched_cond: 'Schedule_conditions'
};

// Scheduler rows: per-row fields of the 26.5.1 flow (state/toggle_item/action/hour/minutes/day/override/condition; topic only row 1). setpoint/target do not exist in 26.5.1 and are skipped when undefined.
const SCHED_SUFFIXES = ['state', 'toggle_item', 'action', 'setpoint', 'target',
                        'hour', 'minutes', 'day', 'override', 'topic', 'condition'];
for (let i = 1; i <= 10; i++) {
    for (const suf of SCHED_SUFFIXES) {
        OBJECTS['sched_' + i + '_' + suf] = 'Schedule_' + i + '_' + suf;
    }
}

// \"fast\" poll (60 s): keys that look like live state / triggers / limits
const FAST = /state|power|setpoint|active|on_off|limit/i;

const fast = (msg.topic === 'fast');

// ---------- flatten ----------
function flatten(prefix, obj, out) {
    if (obj === null || obj === undefined) return out;
    if (typeof obj !== 'object') { out[prefix] = obj; return out; }
    for (const k of Object.keys(obj)) { if (k === 'chart') continue; flatten(prefix + '.' + k, obj[k], out); }
    return out;
}

const flat = {};

// Plain scalar globals (readback / runtime state, not in F_ objects).
// Missing ones are published as 'unset' so gaps (e.g. Quiet_Mode_Level) are visible.
const SCALARS = [
    'TOP97_Heater_Start_Delta',      // J-series: factory -3 (readback = proof)
    'TOP98_Heater_Stop_Delta',       // factory -1
    'TOP96_Heater_Delay_Time',       // factory 30 min
    'TOP94_Zones_State',
    'TOP99_Buffer_Installed',
    'T_zone_1', 'T_zone_2',
    'VirtualState',
    'Force_DHW_active',
    'F_stored_next_operating_mode',
    'DHW_automation_active', 'DHW_automation_delay', 'DHW_automation_state',
    'DHW_boost_state', 'DHW_threshold_lower', 'DHW_threshold_upper',
    'DHW_SP_HIGH', 'DHW_SP_LOW',
    'Quiet_Mode_Level', 'Quietmode_time', 'Quietmode_on_off', 'Previous_Quiet_Mode_Level',
    'PowerfulMode', 'HolidayMode',
    'Sterilization_active', 'Sterilization_Temp', 'SetForceSterilization',
    'SolarFunction_active',
    'Correction_0_WAR_on_off', 'Correction_1_RTC_on_off', 'Correction_2_softstart_on_off'
];
for (const s of SCALARS) {
    const v = (global.get(s, 'file') !== undefined) ? global.get(s, 'file') : global.get(s);
    flat['nr.' + s] = (v === undefined || v === null) ? 'unset' : v;
}

for (const [prefix, varName] of Object.entries(OBJECTS)) {
    try {
        const o = global.get(varName, 'file');
        if (o !== undefined) flatten(prefix, o, flat);
    } catch (e) { /* object not initialised yet */ }
}

// ---------- publish ----------
const seen = context.get('seen') || {};
const msgs = [];

for (const key of Object.keys(flat)) {
    const v = flat[key];
    if (v === null || v === undefined) continue;
    if (fast && !FAST.test(key)) continue;   // fast tick only publishes state-like keys

    const topic = STATE_BASE + '/' + key;
    const payload = typeof v === 'object' ? JSON.stringify(v) : String(v);

    // discovery config once per key per Node-RED restart
    if (!seen[key]) {
        seen[key] = true;
        const uid = key.toLowerCase().replace(/[^a-z0-9]+/g, '_');
        msgs.push({
            topic: DISC_BASE + '/' + uid + '/config',
            payload: JSON.stringify({
                name: 'NR ' + key,
                unique_id: 'heishamon_nr_' + uid,
                state_topic: topic,
                retain: true,
                device: {
                    identifiers: ['heishamon_nr_flow'],
                    name: 'HeishaMon NR Flow',
                    manufacturer: 'HeishaMoNR bridge'
                }
            }),
            retain: true, qos: 1
        });
    }
    msgs.push({ topic: topic, payload: payload, retain: true, qos: 0 });
}

context.set('seen', seen);

// ---------- dashboard status (v1.2.1, output 2) ----------
const nState = msgs.filter(m => String(m.topic).indexOf('/config') === -1).length;
const now = new Date();
const pad = (x) => String(x).padStart(2, '0');
const at = pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());
const stats = global.get('HAB_stats') || {};
if (fast) { stats.fast = { n: nState, at: at }; } else { stats.full = { n: nState, at: at }; }
global.set('HAB_stats', stats);

return [msgs, { payload: stats }];

// Status view builder: turns the publisher's stats (output 2) into two dashboard texts.
const s = msg.payload || {};
const a = {};
if (s.full) { a.payload = s.full.n + ' (full)'; }
else if (s.fast) { a.payload = s.fast.n + ' (fast)'; }
else { a.payload = 'Waiting for the first publish...'; }

const parts = [];
if (s.fast) parts.push('fast ' + s.fast.at + ' (' + s.fast.n + ')');
if (s.full) parts.push('full ' + s.full.at + ' (' + s.full.n + ')');
const b = { payload: parts.length ? 'Last publish: ' + parts.join(' | ') : '' };
return [a, b];

// Shows the running version on the dashboard (fed by the boot inject).
// After a self-update the flow restarts and the boot inject refreshes this field.
// v1.3.0: the same boot sentence template as the update tab ("Running <thing> version <X>.").
const VERSION = '1.3.0';
msg.payload = 'Running bridge version ' + VERSION + '.';
return msg;

// HA Bridge - GitHub updater (v1.3.0), after the WP update tab trust model:
// loopback-only Admin API, credentials via env vars, pinned raw URLs with
// cache-busters, and a merge that replaces ONLY habridge.* nodes.
// All HTTP goes through one http-request node (method 'use', ret 'obj').
// Phases: ver -> flow -> adminflows -> (token -> adminflows) -> deploy.

const REPO = 'MikeyMan83/HeishamonNR-ha-bridge';
const RAW  = 'https://raw.githubusercontent.com/' + REPO + '/main/';
const VERSION = '1.3.0';
const TAB_ID = 'habridge.tab.0001';
const PINNED_BROKER = '92e5b2c.00a8b5';

const st = context.get('st') || {};
const saveSt = () => context.set('st', st);

const adminBase = env.get('HAB_ADMIN_BASE') || env.get('WPU_ADMIN_BASE') || 'http://127.0.0.1:1880';
const adminUser = env.get('HAB_ADMIN_USER') || env.get('WPU_ADMIN_USER') || '';
const adminPass = env.get('HAB_ADMIN_PASS') || env.get('WPU_ADMIN_PASS') || '';

const bust = Math.floor(Date.now() / 1000);

function semverNewer(a, b) {  // is a newer than b ?
    const A = String(a).split('.').map(Number), B = String(b).split('.').map(Number);
    for (let i = 0; i < 3; i++) { const x = A[i] || 0, y = B[i] || 0; if (x > y) return true; if (x < y) return false; }
    return false;
}
function body(p, what) {  // http node auto-parses JSON, so accept object or string
    if (typeof p !== 'string') return p;
    let o; try { o = JSON.parse(p); } catch (e) { throw new Error(what + ' is not valid JSON'); }
    return o;
}
function req(method, url, payload, headers, phase) {
    return { habPhase: phase, method: method, url: url,
             payload: payload === undefined ? '' : payload, headers: headers || {} };
}
function fail(t) {
    st.pending = null; saveSt();
    return [null, { payload: 'Update failed: ' + t + '.', topic: 'HA Bridge error' }, { payload: 'Update failed: ' + t + '.' }];
}

// ---- network errors arrive through the catch scope ----
if (msg.error && msg.statusCode === undefined) {
    return fail('network error (' + (msg.habPhase || '?') + '): ' + (msg.error.message || msg.error));
}

// ---- buttons ----
if (msg.payload === 'check' || msg.payload === 'update') {
    st.pending = msg.payload;
    saveSt();
    return [req('GET', RAW + 'version.json?t=' + bust, '', { 'Accept': 'application/json' }, 'ver'), null, null];
}

// ---- phase: version.json ----
if (msg.habPhase === 'ver') {
    if (msg.statusCode !== 200) return fail('version.json HTTP ' + msg.statusCode);
    let v; try { v = body(msg.payload, 'version.json'); } catch (e) { return fail(e.message); }
    if (!v.version) return fail('version.json has no version field');
    if (v.flowUrl && String(v.flowUrl).indexOf('https://raw.githubusercontent.com/' + REPO + '/') !== 0) {
        return fail('flowUrl refused (not pinned to ' + REPO + ')');
    }
    st.latest = { version: String(v.version), url: String(v.flowUrl || ''), at: Date.now() };
    saveSt();
    const newer = semverNewer(st.latest.version, VERSION);
    const result = newer
        ? 'Bridge update available: ' + st.latest.version + '. Press [Update from GitHub].'
        : 'Up to date (' + st.latest.version + ').';
    if (st.pending === 'check' || !newer) {
        st.pending = null; saveSt();
        return [null, { payload: result, topic: 'HA Bridge' }, { payload: result }];
    }
    return [req('GET', st.latest.url + '?t=' + bust, '', { 'Accept': 'application/json' }, 'flow'), null, { payload: result }];
}

// ---- phase: flow download ----
if (msg.habPhase === 'flow') {
    if (msg.statusCode !== 200) return fail('flow download HTTP ' + msg.statusCode);
    let arr; try { arr = body(msg.payload, 'downloaded file'); } catch (e) { return fail(e.message); }
    if (!Array.isArray(arr)) return fail('downloaded file is not a flow array');
    if (new Set(arr.map(n => n.id)).size !== arr.length) return fail('duplicate ids in downloaded file');
    for (const n of arr) if (String(n.id).indexOf('habridge.') !== 0) return fail('non-bridge node id in downloaded file: ' + n.id);
    const tab = arr.find(n => n.id === TAB_ID);
    if (!tab || tab.type !== 'tab') return fail('tab node missing in downloaded file');
    const m = String(tab.info || '').match(/v(\d+\.\d+\.\d+)/);
    if (!m || m[1] !== st.latest.version) return fail('file version does not match version.json');
    st.newFlow = arr; saveSt();
    const h = { 'Accept': 'application/json' };
    if (st.token) h['Authorization'] = 'Bearer ' + st.token;
    return [req('GET', adminBase + '/flows', '', h, 'adminflows'), null,
            { payload: 'Downloaded bridge ' + st.latest.version + '. Deploying...' }];
}

// ---- phase: current flows ----
if (msg.habPhase === 'adminflows') {
    if (msg.statusCode === 401) {
        if (!adminUser || !adminPass) {
            return fail('Admin login required but no credentials (set HAB_ADMIN_USER / HAB_ADMIN_PASS env vars)');
        }
        return [req('POST', adminBase + '/auth/token',
                    JSON.stringify({ client_id: 'node-red-admin', grant_type: 'password', username: adminUser, password: adminPass }),
                    { 'Content-Type': 'application/json' }, 'token'), null, null];
    }
    if (msg.statusCode !== 200) return fail('GET /flows HTTP ' + msg.statusCode);
    let current, rev;
    try {
        const o = body(msg.payload, 'current flows');
        if (Array.isArray(o)) { current = o; }
        else { current = o.flows; rev = o.rev; }
    } catch (e) { return fail(e.message); }
    if (!Array.isArray(current)) return fail('current flows not an array');

    // merge: replace ONLY habridge.* nodes, everything else untouched
    const merged = current.filter(n => String(n.id).indexOf('habridge.') !== 0).concat(st.newFlow);

    // broker rescue: if the pinned broker config id does not exist locally,
    // point the bridge MQTT nodes at the locally most-used broker
    if (!current.some(n => n.id === PINNED_BROKER && n.type === 'mqtt-broker')) {
        const counts = {};
        for (const n of current) {
            if (typeof n.broker === 'string' && (n.type === 'mqtt in' || n.type === 'mqtt out')) counts[n.broker] = (counts[n.broker] || 0) + 1;
        }
        const local = Object.keys(counts).sort((a, b) => counts[b] - counts[a])[0];
        if (local) for (const n of st.newFlow) if (n.type === 'mqtt out' || n.type === 'mqtt in') n.broker = local;
    }
    st.newFlow = null; saveSt();
    const h = { 'Content-Type': 'application/json' };
    if (st.token) h['Authorization'] = 'Bearer ' + st.token;
    let postBody;
    if (rev !== undefined) { h['Node-RED-API-Version'] = 'v2'; postBody = JSON.stringify({ flows: merged, rev: rev }); }
    else { postBody = JSON.stringify(merged); }
    return [req('POST', adminBase + '/flows', postBody, h, 'deploy'), null,
            { payload: 'Deploying bridge ' + st.latest.version + '...' }];
}

// ---- phase: auth token ----
if (msg.habPhase === 'token') {
    if (msg.statusCode !== 200) return fail('admin login HTTP ' + msg.statusCode);
    let t; try { t = body(msg.payload, 'token response'); } catch (e) { return fail(e.message); }
    if (!t.access_token) return fail('no access_token in login response');
    st.token = t.access_token; st.tokenAt = Date.now(); saveSt();
    const h = { 'Accept': 'application/json', 'Authorization': 'Bearer ' + st.token };
    return [req('GET', adminBase + '/flows', '', h, 'adminflows'), null, null];
}

// ---- phase: deploy result ----
if (msg.habPhase === 'deploy') {
    st.pending = null; saveSt();
    if (msg.statusCode === 200 || msg.statusCode === 204) {
        return [null,
            { payload: 'Bridge update succeeded: now running ' + st.latest.version + '. Fields refresh after the restart.', topic: 'HA Bridge' },
            { payload: 'Last update: ' + st.latest.version + ' (ok).' }];
    }
    if (msg.statusCode === 409) {
        return [null,
            { payload: 'Update failed: flows changed meanwhile (rev conflict). Press [Update from GitHub] again.', topic: 'HA Bridge error' },
            { payload: 'Update failed: flows changed meanwhile (rev conflict). Press [Update from GitHub] again.' }];
    }
    return fail('deploy HTTP ' + msg.statusCode);
}

return null;
